    },
    "pinned_dependencies": {
      "$ref": "#/$defs/QualityCheckModel"
    },
    "typos": {
      "$ref": "#/$defs/QualityCheckModel"
    },
    "tests_or_solution_in_image": {
      "$ref": "#/$defs/QualityCheckModel"
    },
    "test_deps_in_image": {
      "$ref": "#/$defs/QualityCheckModel"
    },
    "hardcoded_solution": {
      "$ref": "#/$defs/QualityCheckModel"
    },
    "file_reference_mentioned": {
      "$ref": "#/$defs/QualityCheckModel"
    }
  },
  "required": [
    "behavior_in_task_description",
    "behavior_in_tests",
